      <div className="min-w-0 flex-1">
        <p className="truncate text-sm font-medium text-zinc-100">{name}</p>
      </div>

      <span className="inline-flex items-center px-2 py-0.5 rounded-full bg-zinc-800 text-xs text-zinc-300">
        {status}
      </span>
    </div>
  );
}
